INSERT INTO public.spesies (id, nama_umum, nama_ilmiah, deskripsi, status_verifikasi, is_verified) VALUES ('LPD-001', 'ADONIS', 'Lysandra bellargus', 'Kupu-kupu berwarna biru cerah pada bagian atas sayap jantan dengan pola hitam di tepinya.', 'TERVERIFIKASI', true);
INSERT INTO public.spesies (id, nama_umum, nama_ilmiah, deskripsi, status_verifikasi, is_verified) VALUES ('LPD-002', 'AMERICAN SNOOT', 'Libytheana carinenta', 'Memiliki ciri khas moncong panjang yang menyerupai paruh kecil pada bagian kepala.', 'TERVERIFIKASI', true);
INSERT INTO public.spesies (id, nama_umum, nama_ilmiah, deskripsi, status_verifikasi, is_verified) VALUES ('LPD-003', 'AN 88', 'Diaethria clymena', 'Memiliki pola unik menyerupai angka 88 pada bagian bawah sayap.', 'TERVERIFIKASI', true);
INSERT INTO public.spesies (id, nama_umum, nama_ilmiah, deskripsi, status_verifikasi, is_verified) VALUES ('LPD-004', 'BANDED PEACOCK', 'Papilio palinurus', 'Memiliki warna hijau metalik dengan pita gelap melintang pada sayap.', 'TERVERIFIKASI', true);
INSERT INTO public.spesies (id, nama_umum, nama_ilmiah, deskripsi, status_verifikasi, is_verified) VALUES ('LPD-005', 'BECKERS WHITE', 'Pontia beckerii', 'Kupu-kupu berwarna putih dengan bercak gelap halus di bagian ujung sayap.', 'TERVERIFIKASI', true);
INSERT INTO public.spesies (id, nama_umum, nama_ilmiah, deskripsi, status_verifikasi, is_verified) VALUES ('LPD-006', 'BLACK HAIRSTREAK', 'Satyrium pruni', 'Memiliki warna cokelat gelap dengan garis oranye kecil dan ekor halus di bagian sayap belakang.', 'TERVERIFIKASI', true);
INSERT INTO public.spesies (id, nama_umum, nama_ilmiah, deskripsi, status_verifikasi, is_verified) VALUES ('LPD-007', 'CABBAGE WHITE', 'Pieris rapae', 'Kupu-kupu putih kecil yang umum ditemukan dengan bintik hitam kecil di sayap depan.', 'PENDING_REVIEW', false);
INSERT INTO public.spesies (id, nama_umum, nama_ilmiah, deskripsi, status_verifikasi, is_verified) VALUES ('LPD-008', 'CHESTNUT', 'Ariadne merione', 'Memiliki warna cokelat kemerahan menyerupai kastanye dengan motif yang sederhana.', 'TERVERIFIKASI', true);
INSERT INTO public.spesies (id, nama_umum, nama_ilmiah, deskripsi, status_verifikasi, is_verified) VALUES ('LPD-009', 'CLODIUS PARNASSIAN', 'Parnassius clodius', 'Memiliki sayap putih transparan dengan bintik merah dan hitam yang khas.', 'TERVERIFIKASI', true);
INSERT INTO public.spesies (id, nama_umum, nama_ilmiah, deskripsi, status_verifikasi, is_verified) VALUES ('LPD-010', 'CLOUDED SULPHUR', 'Colias philodice', 'Kupu-kupu berwarna kuning terang dengan tepian sayap berwarna hitam gelap.', 'TERVERIFIKASI', true);
INSERT INTO public.spesies (id, nama_umum, nama_ilmiah, deskripsi, status_verifikasi, is_verified) VALUES ('LPD-011', 'COPPER TAIL', 'Lycaena pyrrhogaster', 'Memiliki ekor berwarna tembaga kemerahan yang berkilau di bagian bawah sayap.', 'TERVERIFIKASI', true);
INSERT INTO public.spesies (id, nama_umum, nama_ilmiah, deskripsi, status_verifikasi, is_verified) VALUES ('LPD-012', 'CRECENT', 'Phyciodes tharos', 'Kupu-kupu kecil dengan pola warna jingga-hitam menyerupai bulan sabit.', 'TERVERIFIKASI', true);
INSERT INTO public.spesies (id, nama_umum, nama_ilmiah, deskripsi, status_verifikasi, is_verified) VALUES ('LPD-013', 'CRIMSON PATCH', 'Chlosyne janais', 'Memiliki bercak merah tua (crimson) yang mencolok pada sayap hitamnya.', 'TERVERIFIKASI', true);
INSERT INTO public.spesies (id, nama_umum, nama_ilmiah, deskripsi, status_verifikasi, is_verified) VALUES ('LPD-014', 'EASTERN COMA', 'Polygonia comma', 'Memiliki sayap bergelombang dengan tanda putih menyerupai tanda koma di bagian bawah sayap.', 'PENDING_REVIEW', false);
INSERT INTO public.spesies (id, nama_umum, nama_ilmiah, deskripsi, status_verifikasi, is_verified) VALUES ('LPD-015', 'GOLD BANDED', 'Autochton cellus', 'Kupu-kupu dengan pita berwarna emas kekuningan yang melintang di sayap cokelat gelapnya.', 'TERVERIFIKASI', true);
INSERT INTO public.spesies (id, nama_umum, nama_ilmiah, deskripsi, status_verifikasi, is_verified) VALUES ('LPD-016', 'GREAT EGGFLY', 'Hypolimnas bolina', 'Memiliki pola bercak besar pada sayap dengan motif melingkar biru-putih yang khas pada jantan.', 'TERVERIFIKASI', true);
INSERT INTO public.spesies (id, nama_umum, nama_ilmiah, deskripsi, status_verifikasi, is_verified) VALUES ('LPD-017', 'GREY HAIRSTREAK', 'Strymon melinus', 'Sayap berwarna abu-abu dengan bintik oranye kecil dan ekor tipis di bagian belakang.', 'TERVERIFIKASI', true);
INSERT INTO public.spesies (id, nama_umum, nama_ilmiah, deskripsi, status_verifikasi, is_verified) VALUES ('LPD-018', 'INDRA SWALLOW', 'Papilio indra', 'Kupu-kupu hitam besar dengan ekor khas swallowtail dan barisan bintik kuning krem.', 'TERVERIFIKASI', true);
INSERT INTO public.spesies (id, nama_umum, nama_ilmiah, deskripsi, status_verifikasi, is_verified) VALUES ('LPD-019', 'JULIA', 'Dryas iulia', 'Memiliki sayap oranye terang yang memanjang dengan motif garis hitam tipis.', 'TERVERIFIKASI', true);
INSERT INTO public.spesies (id, nama_umum, nama_ilmiah, deskripsi, status_verifikasi, is_verified) VALUES ('LPD-020', 'LARGE MARBLE', 'Euchloe ausonides', 'Memiliki pola guratan hijau-putih seperti marmer di bagian bawah sayap.', 'TERVERIFIKASI', true);
INSERT INTO public.spesies (id, nama_umum, nama_ilmiah, deskripsi, status_verifikasi, is_verified) VALUES ('LPD-021', 'MALACHITE', 'Siproeta stelenes', 'Berwarna hijau muda berkilau menyerupai batu malakit dengan pola hitam kontras.', 'PENDING_REVIEW', false);
INSERT INTO public.spesies (id, nama_umum, nama_ilmiah, deskripsi, status_verifikasi, is_verified) VALUES ('LPD-022', 'MANGROVE SKIPPER', 'Phocides pigmalion', 'Kupu-kupu berbadan kokoh dengan warna cokelat dan kilauan biru di pangkal sayap.', 'TERVERIFIKASI', true);
INSERT INTO public.spesies (id, nama_umum, nama_ilmiah, deskripsi, status_verifikasi, is_verified) VALUES ('LPD-023', 'METALMARK', 'Calephelis borealis', 'Kupu-kupu kecil dengan bintik-bintik mengkilap seperti logam di permukaan sayap.', 'TERVERIFIKASI', true);
INSERT INTO public.spesies (id, nama_umum, nama_ilmiah, deskripsi, status_verifikasi, is_verified) VALUES ('LPD-024', 'MONARCH', 'Danaus plexippus', 'Kupu-kupu ikonik berukuran besar dengan sayap oranye kemerahan dan urat-urat hitam tebal.', 'TERVERIFIKASI', true);
INSERT INTO public.spesies (id, nama_umum, nama_ilmiah, deskripsi, status_verifikasi, is_verified) VALUES ('LPD-025', 'MORNING CLOAK', 'Nymphalis antiopa', 'Sayap berwarna cokelat gelap keunguan dengan pinggiran kuning terang dan bintik biru.', 'TERVERIFIKASI', true);
INSERT INTO public.spesies (id, nama_umum, nama_ilmiah, deskripsi, status_verifikasi, is_verified) VALUES ('LPD-026', 'ORANGE OAKLEAF', 'Kallima inachus', 'Sayap bawah menyerupai daun kering cokelat, namun bagian atas berwarna oranye-biru cerah.', 'TERVERIFIKASI', true);
INSERT INTO public.spesies (id, nama_umum, nama_ilmiah, deskripsi, status_verifikasi, is_verified) VALUES ('LPD-027', 'ORANGE TIP', 'Anthocharis cardamines', 'Ujung sayap depan berwarna oranye terang yang sangat kontras dengan warna dasar putih.', 'TERVERIFIKASI', true);
INSERT INTO public.spesies (id, nama_umum, nama_ilmiah, deskripsi, status_verifikasi, is_verified) VALUES ('LPD-028', 'ORCHARD SWALLOW', 'Papilio aegeus', 'Kupu-kupu swallowtail besar berwarna hitam dengan bercak merah dan putih.', 'PENDING_REVIEW', false);
INSERT INTO public.spesies (id, nama_umum, nama_ilmiah, deskripsi, status_verifikasi, is_verified) VALUES ('LPD-029', 'PAINTED LADY', 'Vanessa cardui', 'Memiliki pola kompleks berwarna oranye, hitam, dan putih dengan bintik-bintik halus.', 'TERVERIFIKASI', true);
INSERT INTO public.spesies (id, nama_umum, nama_ilmiah, deskripsi, status_verifikasi, is_verified) VALUES ('LPD-030', 'PAPER KITE', 'Idea leuconoe', 'Sayap putih transparan dengan pola garis-garis hitam tipis seperti layang-layang kertas.', 'TERVERIFIKASI', true);
INSERT INTO public.spesies (id, nama_umum, nama_ilmiah, deskripsi, status_verifikasi, is_verified) VALUES ('LPD-031', 'PEACOCK', 'Aglais io', 'Memiliki pola lingkaran mata besar berwarna-warni menyerupai ekor burung merak.', 'TERVERIFIKASI', true);
INSERT INTO public.spesies (id, nama_umum, nama_ilmiah, deskripsi, status_verifikasi, is_verified) VALUES ('LPD-032', 'PINE WHITE', 'Neophasia menapia', 'Kupu-kupu putih bersih dengan urat hitam halus, sering ditemukan di hutan pinus.', 'TERVERIFIKASI', true);
INSERT INTO public.spesies (id, nama_umum, nama_ilmiah, deskripsi, status_verifikasi, is_verified) VALUES ('LPD-033', 'PIPEVINE SWALLOW', 'Battus philenor', 'Kupu-kupu swallowtail hitam dengan kilauan biru metalik di sayap belakang.', 'TERVERIFIKASI', true);
INSERT INTO public.spesies (id, nama_umum, nama_ilmiah, deskripsi, status_verifikasi, is_verified) VALUES ('LPD-034', 'PURPLE HAIRSTREAK', 'Favonius quercus', 'Memiliki kilauan warna ungu kebiruan yang indah di bagian atas sayap cokelatnya.', 'TERVERIFIKASI', true);
INSERT INTO public.spesies (id, nama_umum, nama_ilmiah, deskripsi, status_verifikasi, is_verified) VALUES ('LPD-035', 'QUESTION MARK', 'Polygonia interrogationis', 'Memiliki tanda perak menyerupai tanda tanya pada bagian bawah sayap.', 'PENDING_REVIEW', false);
INSERT INTO public.spesies (id, nama_umum, nama_ilmiah, deskripsi, status_verifikasi, is_verified) VALUES ('LPD-036', 'RED ADMIRAL', 'Vanessa atalanta', 'Memiliki pita merah-oranye melintang di sayap hitam dengan bintik putih di ujungnya.', 'TERVERIFIKASI', true);
INSERT INTO public.spesies (id, nama_umum, nama_ilmiah, deskripsi, status_verifikasi, is_verified) VALUES ('LPD-037', 'RED SPOTTED PURPLE', 'Limenitis arthemis', 'Kupu-kupu biru gelap dengan bintik-bintik oranye-merah di bagian bawah sayap.', 'TERVERIFIKASI', true);
INSERT INTO public.spesies (id, nama_umum, nama_ilmiah, deskripsi, status_verifikasi, is_verified) VALUES ('LPD-038', 'SCARCE SWALLOW', 'Iphiclides podalirius', 'Kupu-kupu swallowtail berwarna kuning pucat dengan garis-garis hitam vertikal menyerupai zebra.', 'TERVERIFIKASI', true);
INSERT INTO public.spesies (id, nama_umum, nama_ilmiah, deskripsi, status_verifikasi, is_verified) VALUES ('LPD-039', 'SILVER SPOT SKIPPER', 'Epargyreus clarus', 'Memiliki bercak perak mengkilap yang mencolok di bagian bawah sayap belakang.', 'TERVERIFIKASI', true);
INSERT INTO public.spesies (id, nama_umum, nama_ilmiah, deskripsi, status_verifikasi, is_verified) VALUES ('LPD-040', 'SIXSPOT BURNET', 'Zygaena filipendulae', 'Ngengat siang hari berwarna hitam dengan enam bercak merah terang pada sayap depan.', 'TERVERIFIKASI', true);
INSERT INTO public.spesies (id, nama_umum, nama_ilmiah, deskripsi, status_verifikasi, is_verified) VALUES ('LPD-041', 'SKIPPER', 'Hesperiidae', 'Kupu-kupu kecil dengan tubuh tegap dan antena melengkung khas.', 'TERVERIFIKASI', true);
INSERT INTO public.spesies (id, nama_umum, nama_ilmiah, deskripsi, status_verifikasi, is_verified) VALUES ('LPD-042', 'SOOTYWING', 'Pholisora catullus', 'Memiliki sayap hitam pekat menyerupai jelaga dengan bintik-bintik putih kecil.', 'PENDING_REVIEW', false);
INSERT INTO public.spesies (id, nama_umum, nama_ilmiah, deskripsi, status_verifikasi, is_verified) VALUES ('LPD-043', 'SOUTHERN DOGFACE', 'Zerene cesonia', 'Pola kuning-hitam di sayap depan menyerupai siluet kepala anjing pudel.', 'TERVERIFIKASI', true);
INSERT INTO public.spesies (id, nama_umum, nama_ilmiah, deskripsi, status_verifikasi, is_verified) VALUES ('LPD-044', 'STRAITED QUEEN', 'Danaus eresimus', 'Kupu-kupu berwarna cokelat oranye dengan pola garis-garis putih halus di sepanjang urat sayap.', 'TERVERIFIKASI', true);
INSERT INTO public.spesies (id, nama_umum, nama_ilmiah, deskripsi, status_verifikasi, is_verified) VALUES ('LPD-045', 'TWO BARRED FLASHER', 'Astraptes fulgerator', 'Memiliki dua pita hijau mengkilap di sayap cokelat gelap dan terbang sangat cepat.', 'TERVERIFIKASI', true);
INSERT INTO public.spesies (id, nama_umum, nama_ilmiah, deskripsi, status_verifikasi, is_verified) VALUES ('LPD-046', 'ULYSES', 'Papilio ulysses', 'Kupu-kupu swallowtail besar dengan warna biru elektrik yang sangat menakjubkan.', 'TERVERIFIKASI', true);
INSERT INTO public.spesies (id, nama_umum, nama_ilmiah, deskripsi, status_verifikasi, is_verified) VALUES ('LPD-047', 'VICEROY', 'Limenitis archippus', 'Sangat menyerupai kupu-kupu Monarch, namun memiliki garis hitam tambahan melintang di sayap belakang.', 'TERVERIFIKASI', true);
INSERT INTO public.spesies (id, nama_umum, nama_ilmiah, deskripsi, status_verifikasi, is_verified) VALUES ('LPD-048', 'WOOD SATYR', 'Megisto cymela', 'Memiliki pola beberapa mata lingkaran kecil berwarna cokelat di sayapnya.', 'TERVERIFIKASI', true);
INSERT INTO public.spesies (id, nama_umum, nama_ilmiah, deskripsi, status_verifikasi, is_verified) VALUES ('LPD-049', 'YELLOW SWALLOW TAIL', 'Papilio rutulus', 'Kupu-kupu swallowtail berwarna kuning cerah dengan pola garis hitam tebal.', 'PENDING_REVIEW', false);
